  /* у этих приёмов свои узкие объяснения — их не заменяем общим текстом темы */
  var OWN={z1_dbl:1,z1_mul:1,z1_sub:1,z1_chain:1,z1_est:1};
  function topic(id,o,prefix){
    var k=K[id]=K[id]||{};
    Object.keys(o).forEach(function(f){k[f]=o[f];});
    if(prefix)Object.keys(X.skillGuides).forEach(function(s){
      if(s.indexOf(prefix)===0&&!OWN[s]){var g=X.skillGuides[s];g.plain=k.plain;g.steps=k.steps;g.example=k.example;}
    });
  }

